class Surface : Panel {
 public Surface(){DoubleBuffered=true;BackColor=Color.FromArgb(27,31,40);Padding=new Padding(20);Margin=new Padding(7);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var p=new Pen(Color.FromArgb(60,68,82)))using(var shape=Shape(new Rectangle(0,0,Width-1,Height-1),14))e.Graphics.DrawPath(p,shape);}
 internal static GraphicsPath Shape(Rectangle r,int radius){int d=radius*2;var p=new GraphicsPath();p.AddArc(r.Left,r.Top,d,d,180,90);p.AddArc(r.Right-d,r.Top,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.Left,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
class SoftButton : Button {
 bool hover;
 public SoftButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);DoubleBuffered=true;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
 protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;Control background=Parent;while(background!=null && background.BackColor.A<255)background=background.Parent;e.Graphics.Clear(background==null?Color.FromArgb(27,31,40):background.BackColor);using(var shape=Surface.Shape(new Rectangle(0,0,Width-1,Height-1),8))using(var brush=new SolidBrush(!Enabled?Color.FromArgb(32,37,46):hover?ControlPaint.Light(BackColor,.12f):BackColor))e.Graphics.FillPath(brush,shape);var textBounds=ClientRectangle;textBounds.Inflate(-12,0);TextRenderer.DrawText(e.Graphics,Text,Font,textBounds,Enabled?ForeColor:Color.FromArgb(108,118,135),(TextAlign==ContentAlignment.MiddleLeft?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter)|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
}
