class Meter : Control {
 public double Value;
 public Meter(){DoubleBuffered=true;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;Height=10;}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(Width<4 || Height<4)return;using(var shape=Surface.Shape(new Rectangle(0,0,Width-1,Height-1),Height/2-1))using(var b=new SolidBrush(Color.FromArgb(65,74,88)))e.Graphics.FillPath(b,shape);int width=(int)((Width-1)*Math.Max(0,Math.Min(1,Value)));if(width>4)using(var shape=Surface.Shape(new Rectangle(0,0,width,Height-1),Height/2-1))using(var b=new SolidBrush(Color.FromArgb(132,242,187)))e.Graphics.FillPath(b,shape);}
}
class AlbumView : Control {
 public Image Cover;
 public AlbumView(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(Cover!=null){e.Graphics.DrawImage(Cover,ClientRectangle);return;}using(var brush=new LinearGradientBrush(ClientRectangle,Color.FromArgb(52,45,95),Color.FromArgb(26,56,63),45))e.Graphics.FillRectangle(brush,ClientRectangle);Brand.Draw(e.Graphics,ClientRectangle);}
 protected override void Dispose(bool disposing){if(disposing && Cover!=null)Cover.Dispose();base.Dispose(disposing);}
}
