 internal void Navigate(bool queue,bool settings,bool about=false){logHost.Visible=false;queuePage=queue;dashboardHost.Visible=!settings && !about;settingsHost.Visible=settings && !about;aboutHost.Visible=about;if(about)aboutHost.BringToFront();else if(settings)settingsHost.BringToFront();else dashboardHost.BringToFront();queueRules.Visible=!queue;queueLower.ColumnStyles[0].SizeType=SizeType.Percent;queueLower.ColumnStyles[0].Width=queue?100:67;queueLower.ColumnStyles[1].SizeType=queue?SizeType.Absolute:SizeType.Percent;queueLower.ColumnStyles[1].Width=queue?0:33;topCards.Visible=!queue;dashboard.RowStyles[1].Height=queue?0:270;heading.Text=L.T(queue?"Очередь заказов":"Пульт трансляции");foreach(var button in new[]{navOverview,navQueue,navSettings,navAbout,navLog})button.BackColor=Color.FromArgb(30,35,45);(about?navAbout:settings?navSettings:queue?navQueue:navOverview).BackColor=Color.FromArgb(43,74,64);}
 void ThemeInputs(Control parent){foreach(Control c in parent.Controls){if(c is TextBoxBase || c is ComboBox || c is NumericUpDown){c.BackColor=Color.FromArgb(34,40,51);c.ForeColor=ForeColor;}ThemeInputs(c);}}
 static int Lines(string text){return (text??"").Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Count(x=>!string.IsNullOrWhiteSpace(x));}
 static string Clock(long milliseconds){var t=TimeSpan.FromMilliseconds(Math.Max(0,milliseconds));return ((int)t.TotalMinutes)+":"+t.Seconds.ToString("00");}
 void RefreshDashboard(){
  if(activityLine==null)return;emptyQueue.Visible=orders.Items.Count==0;if(emptyQueue.Visible)emptyQueue.BringToFront();heading.Text=L.T(queuePage?"Очередь заказов":"Пульт трансляции");
  playbackPanel.Text=string.IsNullOrEmpty(e.TrackTitle)?L.T("Музыка ещё не играет"):e.TrackTitle;artistLine.Text=e.TrackArtist;
  voteNumber.Text=e.SkipVotes+" / "+(e.SkipThreshold>0?e.SkipThreshold.ToString():"—");voteMeter.Value=e.SkipThreshold>0?(double)e.SkipVotes/e.SkipThreshold:0;voteMeter.Invalidate();
  timeLine.Text=Clock(e.TrackProgress)+" / "+Clock(e.TrackDuration);trackMeter.Value=e.TrackDuration>0?(double)e.TrackProgress/e.TrackDuration:0;trackMeter.Invalidate();
  ruleLimit.Text=L.T("Длительность: ")+(e.S.maxTrackMinutes==0?L.T("Без лимита"):e.S.maxTrackMinutes+L.T(" мин"));ruleExplicit.Text="Explicit: "+L.T(e.S.blockExplicit?"Запрещён":"Разрешён");ruleTracks.Text=L.T("Запрещённые треки: ")+Lines(e.S.blockedTracks);ruleArtists.Text=L.T("Запрещённые исполнители: ")+Lines(e.S.blockedArtists);lock(e.Gate)queueCount.Text=e.S.orders.Count(o=>o.status!="done" && o.status!="canceled").ToString();manualSkip.Enabled=running!=null && e.Chat!=null;resetVotes.Enabled=manualSkip.Enabled;
  if(coverUrl!=e.TrackImage){coverUrl=e.TrackImage;LoadCover(coverUrl);}
 }
 async void LoadCover(string url){
  int request=++coverRequest;if(album.Cover!=null){album.Cover.Dispose();album.Cover=null;album.Invalidate();}
  Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri) || uri.Scheme!="https" || uri.Host!="i.scdn.co" || !uri.IsDefaultPort || uri.UserInfo!="")return;
  try{using(var response=await covers.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>2*1024*1024)return;using(var stream=await response.Content.ReadAsStreamAsync())using(var bytes=new MemoryStream()){var buffer=new byte[8192];int read;while((read=await stream.ReadAsync(buffer,0,buffer.Length))>0){if(bytes.Length+read>2*1024*1024)return;bytes.Write(buffer,0,read);}bytes.Position=0;using(var image=Image.FromStream(bytes)){if(image.Width>3000 || image.Height>3000)return;var copy=new Bitmap(image);if(IsDisposed || request!=coverRequest){copy.Dispose();return;}album.Cover=copy;album.Invalidate();}}}}catch(Exception){/* Keep the local artwork placeholder if the cover is unavailable. */}
 }
}
